/*	name:	bfont.r	type:	Rez		This is the resource description file that defines the BIT# resource type.Programmers:AGR	Arthur RymanChange History:AGR	V100	1992/12/03	Created.*/type 'BIT#' {	integer = $$countof(glyphs);				// nGlyphs	maxHeight:	integer;									// maxHeight	rowBytes:	integer;									// rowBytes	wide array glyphs {		integer;								// offset		byte;									// height		byte;									// width		byte;									// center_v		byte;									// center_h	};	hex string [$$word(rowBytes) * $$word(maxHeight)];};